class Emitter {
  private handlers = new Map<string, Array<(payload: number) => void>>();

  on(event: string, fn: (payload: number) => void): this {
    const list = this.handlers.get(event) ?? [];
    list.push(fn);
    this.handlers.set(event, list);
    return this;
  }

  emit(event: string, payload: number): void {
    for (const fn of this.handlers.get(event) ?? []) fn(payload);  // plain calls
  }
}

class Stats {
  total = 0;
  record(n: number): void { this.total += n; }
}

const stats = new Stats();
new Emitter()
  .on('sale', n => stats.record(n))          // arrow keeps the receiver
  .on('sale', stats.record.bind(stats))      // so does bind
  .emit('sale', 5);
console.log(stats.total);                    // 10

