class Tally {
  value: number;
  private history: number[] = [];

  constructor(start: number) {
    this.value = start;
  }

  add(n: number): void {
    this.history.push(this.value);
    this.value += n;
  }

  times(n: number): void {
    this.history.push(this.value);
    this.value *= n;
  }

  undo(): void {
    const previous = this.history.pop();
    if (previous !== undefined) this.value = previous;
  }
}

function runCommands(start: number, commands: [string, number][]): number[] {
  const tally = new Tally(start);
  // TODO: these handlers forget their receiver, and table[name] also finds Object.prototype keys
  const table: Record<string, (n: number) => void> = {
    add: tally.add,
    times: tally.times,
    undo: tally.undo,
  };
  const seen: number[] = [];
  for (const [name, n] of commands) {
    const handler = table[name];
    if (handler) handler(n);
    seen.push(tally.value);
  }
  return seen;
}

solution:
function runCommands(start: number, commands: [string, number][]): number[] {
  const tally = new Tally(start);
  const table = new Map<string, (n: number) => void>([
    ['add', n => tally.add(n)],
    ['times', tally.times.bind(tally)],
    ['undo', () => tally.undo()],
  ]);
  const seen: number[] = [];
  for (const [name, n] of commands) {
    table.get(name)?.(n);
    seen.push(tally.value);
  }
  return seen;
}

Every handler now carries its receiver: the arrows close over `tally` and call it with a dot, and `bind` returns a function whose `this` is fixed to `tally` whatever the call site does. Using a `Map` instead of an object literal removes the second bug: only the three keys that were put in exist, so `valueOf`, `toString`, `constructor` and `__proto__` are simply missing and skipped by the optional call. The table is built once, so dispatch is O(1) per command and the whole run is O(commands). `Tally` itself is unchanged: its methods stay on the prototype and are shared, and only the table entries pay for a small closure each.

