type Scalar = string | number | boolean | null;

function lookupChain(layers: Record<string, Scalar>[], keys: string[]): ([Scalar, number] | null)[] {
  let top: object | null = null;
  for (let i = layers.length - 1; i >= 0; i--) {
    top = Object.assign(Object.create(top) as object, layers[i]);
  }
  return keys.map((key): [Scalar, number] | null => {
    let depth = 0;
    for (let obj = top; obj !== null; obj = Object.getPrototypeOf(obj) as object | null) {
      if (Object.hasOwn(obj, key)) return [(obj as Record<string, Scalar>)[key], depth];
      depth++;
    }
    return null;
  });
}

function construct<T extends object, A extends unknown[]>(ctor: (this: T, ...args: A) => unknown, ...args: A): T {
  const proto: unknown = ctor.prototype;
  const linked = typeof proto === 'object' && proto !== null ? proto : Object.prototype;
  const instance = Object.create(linked) as T;
  const result = ctor.apply(instance, args);
  const isObject = (typeof result === 'object' && result !== null) || typeof result === 'function';
  return isObject ? (result as T) : instance;
}

