exercises.starter:
interface BoxShape {
  w: number;
  h: number;
  area(): number;
}

function Box(this: BoxShape, w: number, h: number): void {
  this.w = w;
  this.h = h;
}
Box.prototype.area = function (this: BoxShape): number {
  return this.w * this.h;
};

function Square(this: BoxShape, side: number): void {
  Box.call(this, side, side);
}
Square.prototype = Object.create(Box.prototype);
Square.prototype.constructor = Square;

function Legacy(this: BoxShape, w: number, h: number): BoxShape {
  this.w = w;
  this.h = h;
  return { w: 1, h: 1, area: () => 99 };
}

function Prim(this: BoxShape, w: number, h: number): number {
  Box.call(this, w, h);
  return 42;
}
Prim.prototype = Object.create(Box.prototype);

// Emulate `new ctor(...args)` without using `new` or `class`.
function construct<T extends object, A extends unknown[]>(ctor: (this: T, ...args: A) => unknown, ...args: A): T {
  // TODO: link the prototype and honour an object returned by the constructor
  const instance = {} as T;
  ctor.apply(instance, args);
  return instance;
}

function buildAll(specs: [string, number, number][]): [number, boolean, boolean][] {
  const out: [number, boolean, boolean][] = [];
  for (const [kind, a, b] of specs) {
    let shape: BoxShape;
    if (kind === 'box') shape = construct(Box, a, b);
    else if (kind === 'square') shape = construct(Square, a);
    else if (kind === 'legacy') shape = construct(Legacy, a, b);
    else if (kind === 'prim') shape = construct(Prim, a, b);
    else continue;
    out.push([shape.area(), shape instanceof Box, shape instanceof Square]);
  }
  return out;
}

